def replace_question_marks(S):
    n = len(S)
    # Initialize the result string with the same length as S
    result = list(S)

    # Count the number of question marks
    q_count = S.count('?')

    # Calculate the maximum number of "CHEF" substrings possible
    max_chef_count = (q_count + 3) // 4

    # Fill the question marks to form "CHEF" substrings
    for i in range(n):
        if result[i] == '?':
            if max_chef_count > 0:
                if i + 3 < n and result[i+1:i+4] == ['C', 'H', 'E', 'F']:
                    result[i] = 'C'
